import numpy as np
from scipy.optimize import linear_sum_assignment
# Persist tracks and next_id across the entire input; initialize once.
tracks = []
next_id = 1
def iou(a, b):
    ax1, ay1, ax2, ay2 = a; bx1, by1, bx2, by2 = b
    ix1, iy1 = max(ax1, bx1), max(ay1, by1)
    ix2, iy2 = min(ax2, bx2), min(ay2, by2)
    inter = max(0, ix2 - ix1) * max(0, iy2 - iy1)
    area_a = max(0, ax2 - ax1) * max(0, ay2 - ay1)
    area_b = max(0, bx2 - bx1) * max(0, by2 - by1)
    union = area_a + area_b - inter
    return inter / union if union > 0 else 0.0
def new_track(det, tid):
    x1,y1,x2,y2 = det['box']
    return {'id': tid, 'box': det['box'], 'score': det['score'], 'class_id': det['class_id'], 'class': det['class'], 'misses': 0, 'hits': 1, 'trail': [(int((x1+x2)/2), int((y1+y2)/2))]}
def update(detections):
    global tracks, next_id
    if not tracks:
        for det in detections:
            tracks.append(new_track(det, next_id)); next_id += 1
        return [dict(t) for t in tracks]
    if detections:
        cost = np.zeros((len(tracks), len(detections)))
        for i, trk in enumerate(tracks):
            for j, det in enumerate(detections): cost[i,j] = 1 - iou(trk['box'], det['box'])
        row_idx, col_idx = linear_sum_assignment(cost)
    else:
        row_idx, col_idx = np.array([], dtype=int), np.array([], dtype=int)
    matched_tracks, matched_dets = set(), set()
    for r,c in zip(row_idx, col_idx):
        if 1 - cost[r,c] >= 0.3:
            t, d = tracks[r], detections[c]
            t['box'], t['score'], t['class_id'], t['class'] = d['box'], d['score'], d['class_id'], d['class']
            t['hits'] += 1; t['misses'] = 0
            x1,y1,x2,y2 = t['box']
            t['trail'].append((int((x1+x2)/2), int((y1+y2)/2)))
            t['trail'] = t['trail'][-30:]
            matched_tracks.add(r); matched_dets.add(c)
    for i,t in enumerate(tracks):
        if i not in matched_tracks: t['misses'] += 1
    for j,d in enumerate(detections):
        if j not in matched_dets:
            tracks.append(new_track(d, next_id)); next_id += 1
    tracks = [t for t in tracks if t['misses'] <= 15]
    # Missed IDs remain available for association, but are not current observations.
    return [dict(t) for t in tracks if t['misses'] == 0]
